fixes.proposed:
def windows_on(restaurant: Restaurant, weekday: int) -> list[OpeningHours]:
    """Return the windows that start on ``weekday``, earliest first."""
    today = datetime.now().date()
    start_of_week = today - timedelta(days=today.weekday())
    target_date = start_of_week + timedelta(days=weekday)

    found = []
    for window in restaurant.hours:
        if window.weekday == weekday:
            window_start = target_date + timedelta(hours=window.opens)
            if window_start.date() == target_date or window_start.date() == target_date - timedelta(days=7):
                found.append(window)

    return sorted(found, key=lambda window: window.opens)

