    days_in_month = calendar.monthrange(year, month)[1]
    if days_in_month == 0:
        return Decimal(0)
    share = Decimal(covered) / Decimal(days_in_month)
    return (membership.plan.monthly_fee * share).quantize(CENT, rounding=ROUND_HALF_UP)

