def remove_empty(self) -> int:
    """Drop batches with no units left and return how many were dropped."""
    dropped = 0
    for batches in self._batches.values():
        for batch in list(batches):
            if batch.quantity == 0:
                batches.remove(batch)
                dropped += 1
    return dropped
